import{p as c,I as i,o as g,c as u,b6 as r,J as t,w as l,bm as h,bn as p}from"./chunks/framework.COUcLbTA.js";const b=JSON.parse('{"title":"Integrated Development Environment (IDE) Basics","description":"","frontmatter":{},"headers":[],"relativePath":"en/appendix/2-development-tools/ide-basics.md","filePath":"en/appendix/2-development-tools/ide-basics.md"}'),m={name:"en/appendix/2-development-tools/ide-basics.md"},w=Object.assign(m,{setup(f){return c(()=>{const s=()=>{const e=window.location.hash;if(e)try{const o=document.querySelector(decodeURIComponent(e));o&&o.tagName==="DETAILS"&&o.setAttribute("open","");const n=o?.closest("details");n&&n.setAttribute("open","")}catch(o){console.error(o)}};s(),window.addEventListener("hashchange",s)}),(s,e)=>{const o=i("AiHelpDemo"),n=i("VirtualVSCodeDemo"),a=i("ClientOnly"),d=i("IdeArchitectureDemo");return g(),u("div",null,[e[0]||(e[0]=r('<h1 id="integrated-development-environment-ide-basics" tabindex="-1">Integrated Development Environment (IDE) Basics <a class="header-anchor" href="#integrated-development-environment-ide-basics" aria-label="Permalink to “Integrated Development Environment (IDE) Basics”">​</a></h1><div class="tip custom-block"><p class="custom-block-title">💡 Learning Guide</p><p>This chapter will take you deep into the core productivity tool for programmers—the <strong>Integrated Development Environment (IDE)</strong>. We&#39;ll start from the design philosophy of IDEs, analyze their core components one by one, and demonstrate their working principles through a virtual IDE.</p></div><h2 id="what-to-do-when-you-don-t-understand-something-how-to-solve-problems" tabindex="-1">What to Do When You Don&#39;t Understand Something? (How to solve problems) <a class="header-anchor" href="#what-to-do-when-you-don-t-understand-something-how-to-solve-problems" aria-label="Permalink to “What to Do When You Don&#39;t Understand Something? (How to solve problems)”">​</a></h2><p>In the process of learning and using an IDE, you may encounter various buttons, menus, or code errors that you don&#39;t understand. At this time, <strong>don&#39;t panic—using an AI assistant is the most efficient solution</strong>.</p><p><strong>Recommended Approach: Screenshot and Ask AI</strong></p><p>Modern AIs (such as ChatGPT, Claude, DeepSeek, etc.) have powerful image recognition capabilities. When you encounter unfamiliar interface elements or complex code snippets:</p><ol><li><strong>Screenshot</strong>: Capture the part you don&#39;t understand (such as a strange icon or a complex configuration code).</li><li><strong>Ask</strong>: Send the image to AI and ask: &quot;What is this? What&#39;s it for?&quot; or &quot;What does xxx do in this code?&quot;</li><li><strong>Follow up</strong>: If AI&#39;s answer is too technical to understand, continue asking: &quot;Please explain it in plain language, preferably with a real-life example.&quot;</li></ol>',7)),t(o),e[1]||(e[1]=r('<hr><h2 id="_0-introduction-why-do-we-need-an-ide" tabindex="-1">0. Introduction: Why Do We Need an IDE? <a class="header-anchor" href="#_0-introduction-why-do-we-need-an-ide" aria-label="Permalink to “0. Introduction: Why Do We Need an IDE?”">​</a></h2><p>In the software development process, programmers need to frequently write code, manage files, compile and run programs, debug errors, and so on. If all these operations needed to be completed in different independent software (for example, using Notepad to write code, command line to compile, and file folders to manage files), efficiency would be extremely low and error-prone.</p><p>The core value of an <strong>IDE (Integrated Development Environment)</strong> lies in <strong>integration</strong>. It integrates various tools needed for software development (editor, compiler, debugger, file manager, etc.) into a unified graphical interface, providing a one-stop working experience.</p><p><strong>VS Code is one of the most popular IDEs.</strong> Although it is essentially a lightweight code editor, through its powerful plugin system, it has all the core functions of an IDE (code editing, debugging, version control, etc.), and is therefore widely regarded as the preferred IDE for modern frontend and full-stack development.</p><p>In short, IDEs aim to maximize developer productivity and reduce the time cost of switching between different tools.</p><blockquote><p>🔗 <strong>Resource Downloads</strong>:</p><ul><li><a href="https://code.visualstudio.com/Download" target="_blank" rel="noreferrer">VS Code Official Download</a></li><li><a href="https://vscode.dev/" target="_blank" rel="noreferrer">VS Code Web Version Experience</a></li></ul><p><strong>VS Code (Visual Studio Code)</strong> is a free, open-source, cross-platform code editor developed by Microsoft. With its <strong>lightweight nature, rich plugins, and fast startup speed</strong>, it has become one of the most popular development tools worldwide. Whether you&#39;re writing Python, JavaScript, or C++, VS Code can become the most suitable &quot;tool&quot; for you through plugin installation.</p></blockquote><hr><h2 id="_1-core-interface-analysis" tabindex="-1">1. Core Interface Analysis <a class="header-anchor" href="#_1-core-interface-analysis" aria-label="Permalink to “1. Core Interface Analysis”">​</a></h2><p>The interface layout of modern IDEs (taking VS Code as an example) has been carefully designed and usually contains the following four core areas:</p><ol><li><p><strong>Sidebar: Resource Management</strong> Displays the project&#39;s file tree, supports creating, renaming, moving, and deleting files, providing a global view and quick access to the project structure.</p></li><li><p><strong>Editor Area: Code Creation</strong> The core area for writing and modifying code. Supports syntax highlighting, intelligent code completion, syntax checking, and other functions, providing an efficient and intelligent code writing environment.</p></li><li><p><strong>Bottom Panel: Execution and Feedback</strong> Interacts with the underlying system and views running results. Includes Terminal, Output, etc., used for executing commands, viewing logs, and debugging.</p></li><li><p><strong>Activity Bar: Function Navigation</strong> Located on the far left of the interface, containing icons for file explorer, search, Git management, etc., used to quickly switch between different work contexts (such as &quot;writing code&quot; and &quot;submitting code&quot;).</p></li></ol><hr><h2 id="_2-interactive-demo-functional-experience" tabindex="-1">2. Interactive Demo: Functional Experience <a class="header-anchor" href="#_2-interactive-demo-functional-experience" aria-label="Permalink to “2. Interactive Demo: Functional Experience”">​</a></h2><p>Seeing is believing. To let you truly feel the convenience of an IDE, we have prepared a <strong>virtual VS Code environment</strong> for you.</p><p><strong>Please try the following operations</strong>:</p><ol><li>Click the <strong>&quot;▶ Start Auto Tour&quot;</strong> button in the upper right corner to follow the cursor and learn about each area.</li><li><strong>Free Exploration</strong>: Click the icons on the left to switch views, or click file names to open code.</li><li><strong>Experience Integration</strong>: You&#39;ll find that file management, code editing, and terminal running are all seamlessly connected within the same window.</li><li><strong>Install Plugins</strong>: Select <strong>&quot;Extensions Installation&quot;</strong> mode from the dropdown menu to experience how to install Python plugins in a virtual store.</li></ol>',16)),t(a,null,{default:l(()=>[t(n)]),_:1}),e[2]||(e[2]=r('<hr><h2 id="_3-core-mechanism-why-can-vs-code-do-everything" tabindex="-1">3. Core Mechanism: Why Can VS Code Do Everything? <a class="header-anchor" href="#_3-core-mechanism-why-can-vs-code-do-everything" aria-label="Permalink to “3. Core Mechanism: Why Can VS Code Do Everything?”">​</a></h2><p>You might be curious: Why can the same software write Python, C++, and do web development? How does it do it? Actually, VS Code&#39;s design philosophy can be summarized in one sentence: <strong>&quot;Minimalist core, pluggable capabilities.&quot;</strong></p><h3 id="_3-1-minimalist-core-just-a-canvas" tabindex="-1">3.1 Minimalist Core: Just a &quot;Canvas&quot; <a class="header-anchor" href="#_3-1-minimalist-core-just-a-canvas" aria-label="Permalink to “3.1 Minimalist Core: Just a &quot;Canvas&quot;”">​</a></h3><p>Imagine, the VS Code you just downloaded, if no plugins are installed, actually <strong>doesn&#39;t understand programming</strong>. At this point, it is essentially just a <strong>powerful text editor</strong>.</p><ul><li>It is responsible for displaying text (rendering).</li><li>It is responsible for managing files (IO).</li><li>But it doesn&#39;t know that <code>print(&quot;Hello&quot;)</code> is Python code, nor does it know that <code>int main()</code> is a C++ entry point.</li></ul><h3 id="_3-2-plugin-system-injecting-soul" tabindex="-1">3.2 Plugin System: Injecting &quot;Soul&quot; <a class="header-anchor" href="#_3-2-plugin-system-injecting-soul" aria-label="Permalink to “3.2 Plugin System: Injecting &quot;Soul&quot;”">​</a></h3><p>To make VS Code able to &quot;understand&quot; code, we need to install <strong>Extensions</strong>. Plugins are like specialized <strong>translators</strong>:</p><ul><li><strong>Python Plugin</strong>: Tells VS Code what variables are, what functions are, and how to run <code>.py</code> files.</li><li><strong>C++ Plugin</strong>: Tells VS Code how to call the compiler and how to debug memory.</li></ul><p>This design makes VS Code very lightweight—if you don&#39;t write Java, you don&#39;t have to carry Java&#39;s runtime environment.</p><h3 id="_3-3-behind-the-scenes-from-code-to-execution" tabindex="-1">3.3 Behind the Scenes: From Code to Execution <a class="header-anchor" href="#_3-3-behind-the-scenes-from-code-to-execution" aria-label="Permalink to “3.3 Behind the Scenes: From Code to Execution”">​</a></h3>',11)),t(a,null,{default:l(()=>[t(d)]),_:1}),e[3]||(e[3]=r('<p>Let&#39;s look at how VS Code, plugins, and the underlying environment collaborate through a specific scenario. Suppose you write a line of Python code and click <strong>Run</strong> or <strong>Debug</strong>:</p><h4 id="_1-language-recognition-activation" tabindex="-1">1. Language Recognition (Activation) <a class="header-anchor" href="#_1-language-recognition-activation" aria-label="Permalink to “1. Language Recognition (Activation)”">​</a></h4><p>VS Code detects the <code>.py</code> suffix and automatically wakes up the <strong>Python Plugin</strong>. The plugin immediately takes over the editor, begins syntax analysis, colors the code differently (syntax highlighting), and provides intelligent suggestions.</p><h4 id="_2-task-delegation-delegation" tabindex="-1">2. Task Delegation (Delegation) <a class="header-anchor" href="#_2-task-delegation-delegation" aria-label="Permalink to “2. Task Delegation (Delegation)”">​</a></h4><p>When you issue a command, the plugin itself does not directly execute the code, but <strong>delegates</strong> the task to underlying professional tools:</p><ul><li><strong>Run Mode</strong>: The plugin generates a command (such as <code>python main.py</code>) and sends it to the system&#39;s <strong>terminal</strong> for execution.</li><li><strong>Debug Mode</strong>: The plugin starts a <strong>Debug Adapter</strong>. It&#39;s like a &quot;monitoring probe,&quot; connecting to the internals of the Python interpreter, allowing you to control code execution line by line.</li></ul><h4 id="_3-result-feedback-feedback" tabindex="-1">3. Result Feedback (Feedback) <a class="header-anchor" href="#_3-result-feedback-feedback" aria-label="Permalink to “3. Result Feedback (Feedback)”">​</a></h4><p>The Python interpreter (or compiler) executes the code and returns the results (or error messages) to the plugin. The plugin then &quot;carries&quot; this information back and displays it in VS Code&#39;s <strong>bottom terminal panel</strong>.</p><h3 id="_3-4-summary-using-a-restaurant-as-an-analogy" tabindex="-1">3.4 Summary: Using a &quot;Restaurant&quot; as an Analogy <a class="header-anchor" href="#_3-4-summary-using-a-restaurant-as-an-analogy" aria-label="Permalink to “3.4 Summary: Using a &quot;Restaurant&quot; as an Analogy”">​</a></h3><p>If the above formula is a bit abstract, we can imagine the process of writing code as <strong>dining at a restaurant</strong>:</p><ol><li><p><strong>VS Code is the &quot;Restaurant Lobby&quot;</strong>:</p><ul><li>The decoration is luxurious and the environment is comfortable (code highlighting, beautiful themes).</li><li><strong>But the lobby itself doesn&#39;t produce food</strong>. You sit here just to more comfortably &quot;order&quot; (write code).</li></ul></li><li><p><strong>Environment (Python/Node) is the &quot;Kitchen&quot;</strong>:</p><ul><li>This is where the real <strong>cooking (running code)</strong> happens.</li><li>If the restaurant has no kitchen (Python not installed), you can sit in the lobby until dark and still won&#39;t get food.</li></ul></li><li><p><strong>Plugins are the &quot;Waiters&quot;</strong>:</p><ul><li>They connect the lobby and the kitchen.</li><li>They understand your menu, run to tell the kitchen: &quot;Table 3 wants a &#39;run main.py&#39;!&quot;</li><li>When it&#39;s done, they bring the results (steaming hot food) back to you.</li></ul></li></ol><p><strong>Conclusion</strong>:</p><ul><li>Only installing VS Code = <strong>Only lobby, no kitchen</strong> (can only look, can&#39;t eat).</li><li>Only installing Python = <strong>Only kitchen, no lobby</strong> (can eat, but have to squat on the kitchen floor, poor experience).</li><li><strong>Installing VS Code + Plugins + Python = Perfect dining experience.</strong></li></ul><hr><h1 id="appendix-visual-studio-code-menu-bar-analysis" tabindex="-1">Appendix: Visual Studio Code Menu Bar Analysis <a class="header-anchor" href="#appendix-visual-studio-code-menu-bar-analysis" aria-label="Permalink to “Appendix: Visual Studio Code Menu Bar Analysis”">​</a></h1><p>To help everyone understand the meaning of each option, here we provide an in-depth analysis of the menu bar:</p><p><img src="'+h+'" alt=""></p><p><img src="'+p+'" alt=""></p><details class="custom-block details" id="vscode-file-menu"><summary>File: Project and File Open/Save/Workspace Management</summary><p>This menu is mainly responsible for: <strong>Creating/Opening Files</strong>, <strong>Opening Project Folders</strong>, <strong>Managing Workspaces</strong>, <strong>Saving and Closing</strong>.</p><blockquote><p>The most commonly used are: Open Folder to open a project; Open… to open a single file; then use Save / Save All to save changes, and finally use Close Editor / Close Folder to end the current work. Workspace-related content can be slowly learned as you get more projects, no need to understand everything at once.</p></blockquote><ul><li><strong>New Text File</strong>: Create a new unnamed text buffer for temporary notes or quick pasting.</li><li><strong>New File…</strong>: Create a new file in the project (usually asks you to choose path/name).</li><li><strong>New Window</strong>: Open a new VS Code window instance.</li><li><strong>New Window with Profile</strong>: Open a new window with a specified Profile (extension/settings combination), suitable for isolating environments for different courses/projects.</li><li><strong>Open…</strong>: Open a single file for editing.</li><li><strong>Open Folder…</strong>: Open a folder as the project root directory (the most commonly used &quot;open project&quot; method).</li><li><strong>Open Workspace from File…</strong>: Open a <code>.code-workspace</code> file to load a workspace with multiple folders/specific settings.</li><li><strong>Open Recent</strong>: Quickly access recently opened files/folders/workspaces.</li><li><strong>Add Folder to Workspace…</strong>: Add another folder to the current workspace (forming a multi-root workspace).</li><li><strong>Save Workspace As…</strong>: Save the current workspace structure as a <code>.code-workspace</code> file for easy sharing/reuse.</li><li><strong>Duplicate Workspace</strong>: Duplicate the current workspace configuration (commonly used to create similar project environments).</li><li><strong>Save</strong>: Save changes to the current file.</li><li><strong>Save As…</strong>: Save the current file with a new name/path.</li><li><strong>Save All</strong>: Save all opened files that have modifications.</li><li><strong>Share</strong>: Entry related to sharing/collaboration (specific content depends on version and extensions).</li><li><strong>Auto Save</strong>: Toggle auto-save strategy (e.g., delayed save/focus change save).</li><li><strong>Revert File</strong>: Discard unsaved changes to the current file and revert to the disk version.</li><li><strong>Close Editor</strong>: Close the current tab.</li><li><strong>Close Folder</strong>: Close the current project folder (workspace becomes empty).</li><li><strong>Close Window</strong>: Close the current VS Code window.</li></ul></details><details class="custom-block details" id="vscode-edit-menu"><summary>Edit: Basic Editing, Find/Replace, Comments and Quick Edit Actions</summary><p>This menu is mainly responsible for: <strong>Undo/Redo</strong>, <strong>Cut/Copy/Paste</strong>, <strong>Find/Replace</strong>, <strong>Comments and Editor Actions</strong> (improving editing efficiency).</p><ul><li><strong>Undo / Redo</strong>: The most basic operations for when you write code wrong.</li><li><strong>Cut / Copy / Paste</strong>: Text transportation.</li><li><strong>Find / Replace</strong>: Search or batch modify in the current file.</li><li><strong>Find in Files / Replace in Files</strong>: Global (whole project) search and replace, very powerful but use with caution.</li><li><strong>Toggle Line Comment</strong>: <code>Ctrl + /</code>, quickly comment/uncomment the current line.</li><li><strong>Toggle Block Comment</strong>: <code>Shift + Alt + A</code>, quickly comment/uncomment the selected area.</li><li><strong>Emmet: Expand Abbreviation</strong>: A powerful tool for HTML/CSS development, type shorthand and press Tab to expand code.</li></ul></details><details class="custom-block details" id="vscode-selection-menu"><summary>Selection: Multi-cursor and Smart Selection</summary><p>This menu is mainly responsible for: <strong>Cursor Control</strong>, <strong>Multi-line Editing</strong>, <strong>Expand/Shrink Selection</strong>. This is VS Code&#39;s killer feature for improving efficiency.</p><ul><li><strong>Select All</strong>: Select all content in the current file.</li><li><strong>Expand Selection / Shrink Selection</strong>: Intelligently perceive syntax structure, gradually expand or shrink the selection range (e.g., word -&gt; string -&gt; inside parentheses -&gt; whole line -&gt; function body).</li><li><strong>Copy Line Up / Down</strong>: Quickly clone the current line.</li><li><strong>Move Line Up / Down</strong>: <code>Alt + ↑ / ↓</code>, adjust code line order directly without cut and paste.</li><li><strong>Add Cursor Above / Below</strong>: <code>Ctrl + Alt + ↑ / ↓</code>, enable multi-cursor mode to edit multiple lines simultaneously.</li><li><strong>Add Cursor to Line Ends</strong>: After selecting multiple lines of text, add a cursor at the end of each line.</li></ul></details><details class="custom-block details" id="vscode-view-menu"><summary>View: Interface Layout and Panel Control</summary><p>This menu is mainly responsible for: <strong>Toggle Sidebar/Panel</strong>, <strong>Adjust Layout</strong>, <strong>Command Palette</strong>, <strong>Output and Debug Console</strong>.</p><ul><li><strong>Command Palette…</strong>: <code>Ctrl + Shift + P</code> / <code>F1</code>, VS Code&#39;s central command center, can search and execute all commands.</li><li><strong>Open View…</strong>: Quickly open specific sidebar views (such as Explorer, Source Control).</li><li><strong>Appearance</strong>: Control fullscreen, menu bar visibility, sidebar position, zoom level (Zoom In/Out).</li><li><strong>Editor Layout</strong>: Split editor (Split Up/Down/Left/Right) for side-by-side code comparison.</li><li><strong>Explorer / Search / Source Control / Run / Extensions</strong>: Directly switch views in the Activity Bar.</li><li><strong>Problems / Output / Debug Console / Terminal</strong>: Directly control the display content of the bottom panel.</li><li><strong>Word Wrap</strong>: <code>Alt + Z</code>, control whether long lines of code automatically wrap (does not affect actual file content).</li></ul></details><details class="custom-block details" id="vscode-go-menu"><summary>Go: Code Navigation and Jumping</summary><p>This menu is mainly responsible for: <strong>Jumping Between Files</strong>, <strong>Jumping Between Symbols (Functions/Variables)</strong>.</p><ul><li><strong>Back / Forward</strong>: Like a browser, jump between your cursor history positions.</li><li><strong>Switch Editor…</strong>: Quickly switch between opened tabs.</li><li><strong>Go to File…</strong>: <code>Ctrl + P</code>, type filename to quickly open files.</li><li><strong>Go to Symbol in Editor…</strong>: <code>Ctrl + Shift + O</code>, list functions/classes/variables in the current file for quick jumping.</li><li><strong>Go to Definition</strong>: <code>F12</code>, jump to the definition of the variable or function at the cursor.</li><li><strong>Go to References</strong>: <code>Shift + F12</code>, see where this variable or function is used.</li><li><strong>Go to Line/Column…</strong>: <code>Ctrl + G</code>, jump to a specified line number.</li></ul></details><details class="custom-block details" id="vscode-run-menu"><summary>Run: Debugging and Execution</summary><p>This menu is mainly responsible for: <strong>Start Debugging</strong>, <strong>Breakpoint Management</strong>.</p><ul><li><strong>Start Debugging</strong>: <code>F5</code>, run the program in debug mode (supports breakpoints, variable watching).</li><li><strong>Run Without Debugging</strong>: <code>Ctrl + F5</code>, run the program directly without attaching a debugger (slightly faster).</li><li><strong>Stop Debugging</strong>: Forcefully end the current debugging session.</li><li><strong>Restart Debugging</strong>: Run again.</li><li><strong>Toggle Breakpoint</strong>: <code>F9</code>, add or remove a red dot (breakpoint) on the current line.</li><li><strong>New Breakpoint</strong>: Supports conditional breakpoints, log breakpoints, and other advanced features.</li></ul></details><details class="custom-block details" id="vscode-terminal-menu"><summary>Terminal: Integrated Command Line</summary><p>This menu is mainly responsible for: <strong>New Terminal</strong>, <strong>Manage Terminal Windows</strong>.</p><ul><li><strong>New Terminal</strong>: Open a new Shell (PowerShell/Bash/Zsh) in the bottom panel.</li><li><strong>Split Terminal</strong>: Split left/right/up/down in the same terminal panel to run multiple commands simultaneously.</li><li><strong>Run Task…</strong>: Run build/test tasks defined in <code>tasks.json</code>.</li></ul></details><details class="custom-block details" id="vscode-help-menu"><summary>Help: Documentation and Feedback</summary><ul><li><strong>Welcome</strong>: Open the welcome page (contains getting started guide, recent projects).</li><li><strong>Show All Commands</strong>: Same as Command Palette.</li><li><strong>Documentation</strong>: Jump to official documentation.</li><li><strong>Editor Playground</strong>: Interactive tutorial for learning editing techniques.</li><li><strong>Check for Updates…</strong>: Manually check for updates.</li><li><strong>About</strong>: View version number, build time, Electron/Node version information.</li></ul></details>',26))])}}});export{b as __pageData,w as default};
